#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    int **A = (int **)malloc(L * sizeof(int *));
    for (int i = 0; i < L; i++) {
        A[i] = (int *)malloc(C * sizeof(int));
        for (int j = 0; j < C; j++) {
            scanf("%d", &A[i][j]);
        }
    }

    if (L < 2 || C < 2) {
        printf("0\n");
        for (int i = 0; i < L; i++) free(A[i]);
        free(A);
        return 0;
    }

    int R = L - 1;
    int K = C - 1;

    int *height = (int *)calloc(K, sizeof(int));
    int *left = (int *)malloc(K * sizeof(int));
    int *right = (int *)malloc(K * sizeof(int));
    int *stack = (int *)malloc(K * sizeof(int));

    long long max_elements = 0;

    for (int i = 0; i < R; i++) {
        for (int j = 0; j < K; j++) {
            long long d1 = (long long)A[i][j] + A[i + 1][j + 1];
            long long d2 = (long long)A[i][j + 1] + A[i + 1][j];
            if (d1 <= d2) {
                height[j]++;
            } else {
                height[j] = 0;
            }
        }

        int top = -1;
        for (int j = 0; j < K; j++) {
            while (top >= 0 && height[stack[top]] >= height[j]) {
                top--;
            }
            left[j] = (top == -1) ? -1 : stack[top];
            stack[++top] = j;
        }

        top = -1;
        for (int j = K - 1; j >= 0; j--) {
            while (top >= 0 && height[stack[top]] >= height[j]) {
                top--;
            }
            right[j] = (top == -1) ? K : stack[top];
            stack[++top] = j;
        }

        for (int j = 0; j < K; j++) {
            if (height[j] > 0) {
                long long h = height[j];
                long long w = right[j] - left[j] - 1;
                long long elements = (h + 1) * (w + 1);
                if (elements > max_elements) {
                    max_elements = elements;
                }
            }
        }
    }

    printf("%lld\n", max_elements);

    for (int i = 0; i < L; i++) free(A[i]);
    free(A);
    free(height);
    free(left);
    free(right);
    free(stack);

    return 0;
}
